selector_to_html = {"a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u67b6\u6784<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>TransformerEngine-FL \u91c7\u7528\u4e09\u5c42\u63d2\u4ef6\u67b6\u6784\uff0c\u5c06\u7b97\u5b50\u7ba1\u7406\u4e0e\u786c\u4ef6\u7279\u5b9a\u5b9e\u73b0\u89e3\u8026\u3002</p><p><a data-lightbox=\"image-set\" href=\"../_images/te-fl-architecture.PNG\">\n<img alt=\"alt text\" src=\"../_images/te-fl-architecture.PNG\"/></a>\n</p>", "a[href=\"#transformerengine-fl\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">TransformerEngine-FL \u6982\u89c8<a class=\"headerlink\" href=\"#transformerengine-fl\" title=\"Link to this heading\">#</a></h1><p>TransformerEngine-FL \u662f <a class=\"reference external\" href=\"https://github.com/NVIDIA/TransformerEngine\">NVIDIA Transformer Engine</a>\uff08TE\uff09\u7684\u4e00\u4e2a\u5206\u652f\uff0c\u5f15\u5165\u4e86\u57fa\u4e8e\u63d2\u4ef6\u67b6\u6784\u7684\u591a AI \u82af\u7247\u652f\u6301\uff0c\u6784\u5efa\u5728 <a class=\"reference external\" href=\"https://github.com/flagos-ai\">FlagOS</a>\uff08\u7edf\u4e00\u5f00\u6e90 AI \u7cfb\u7edf\u8f6f\u4ef6\u6808\uff09\u4e4b\u4e0a\u3002\u5b83\u5c06 TE \u7684 FP8 \u8bad\u7ec3\u548c\u63a8\u7406\u80fd\u529b\u6269\u5c55\u5230\u591a\u79cd\u786c\u4ef6\u73af\u5883\u4e2d\u3002\u5728\u4e0d\u6539\u53d8 TE \u539f\u6709\u63a5\u53e3\u6216\u4f7f\u7528\u65b9\u5f0f\u7684\u60c5\u51b5\u4e0b\uff0c\u76f8\u540c\u7684\u6a21\u578b\u4ee3\u7801\u53ef\u4ee5\u5728\u4e0d\u540c AI \u82af\u7247\u5e73\u53f0\u4e0a\u8fd0\u884c FP8 \u6df7\u5408\u7cbe\u5ea6\u8bad\u7ec3\u548c\u63a8\u7406\u3002</p><p>Transformer Engine\uff08TE\uff09\u662f\u4e00\u4e2a\u7528\u4e8e\u5728 NVIDIA GPU \u4e0a\u52a0\u901f Transformer \u6a21\u578b\u7684\u5e93\uff0c\u5305\u62ec\u5728 Hopper\u3001Ada \u548c Blackwell GPU \u4e0a\u4f7f\u7528 8 \u4f4d\u6d6e\u70b9\uff08FP8\uff09\u7cbe\u5ea6\uff0c\u4ee5\u66f4\u4f4e\u7684\u663e\u5b58\u5360\u7528\u6765\u63d0\u4f9b\u66f4\u597d\u7684\u8bad\u7ec3\u548c\u63a8\u7406\u6027\u80fd\u3002TE \u63d0\u4f9b\u4e86\u4e00\u7cfb\u5217\u9488\u5bf9\u6d41\u884c Transformer \u67b6\u6784\u7684\u9ad8\u5ea6\u4f18\u5316\u6784\u5efa\u6a21\u5757\uff0c\u4ee5\u53ca\u4e00\u4e2a\u7c7b\u4f3c\u4e8e\u81ea\u52a8\u6df7\u5408\u7cbe\u5ea6\u7684 API\uff0c\u53ef\u4ee5\u65e0\u7f1d\u5730\u4e0e\u60a8\u7684\u6846\u67b6\u7279\u5b9a\u4ee3\u7801\u4e00\u8d77\u4f7f\u7528\u3002TE \u8fd8\u5305\u542b\u4e00\u4e2a\u4e0e\u6846\u67b6\u65e0\u5173\u7684 C++ API\uff0c\u53ef\u4ee5\u4e0e\u5176\u4ed6\u6df1\u5ea6\u5b66\u4e60\u5e93\u96c6\u6210\uff0c\u4e3a Transformer \u542f\u7528 FP8 \u652f\u6301\u3002</p>", "a[href=\"features.html#fp8\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">FP8 \u8bad\u7ec3\u4e0e\u63a8\u7406<a class=\"headerlink\" href=\"#fp8\" title=\"Link to this heading\">#</a></h2>", "a[href=\"features.html#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">FP8 \u6536\u655b\u6027<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>FP8 \u5df2\u5728\u4e0d\u540c\u6a21\u578b\u67b6\u6784\u548c\u914d\u7f6e\u4e0a\u8fdb\u884c\u4e86\u5e7f\u6cdb\u6d4b\u8bd5\uff0c\u6211\u4eec\u53d1\u73b0 FP8 \u548c BF16 \u8bad\u7ec3\u635f\u5931\u66f2\u7ebf\u4e4b\u95f4<strong>\u6ca1\u6709\u663e\u8457\u5dee\u5f02</strong>\u3002FP8 \u5728\u4e0b\u6e38 LLM \u4efb\u52a1\uff08\u4f8b\u5982 LAMBADA \u548c WikiText\uff09\u4e0a\u7684\u51c6\u786e\u6027\u4e5f\u5df2\u5f97\u5230\u9a8c\u8bc1\u3002</p><p>\u5df2\u9a8c\u8bc1\u7684\u6a21\u578b\uff1aT5\uff08770M\u300111B\uff09\u3001MPT\uff081.3B\u300113B\uff09\u3001GPT\uff085B\u300122B\u3001175B\uff09\u3001LLama2\uff087B\u300170B\uff09\u3002</p>", "a[href=\"features.html#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u591a\u540e\u7aef\u67b6\u6784<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>TransformerEngine-FL \u5f15\u5165\u4e86\u4e09\u5c42\u57fa\u4e8e\u63d2\u4ef6\u7684\u7b97\u5b50\u8c03\u5ea6\u7cfb\u7edf\uff0c\u5b9e\u73b0\u82af\u7247\u65e0\u5173\u7684 FP8 \u8bad\u7ec3\u548c\u63a8\u7406\uff1a</p>", "a[href=\"features.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u7279\u6027<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><h2>\u591a\u540e\u7aef\u67b6\u6784<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>TransformerEngine-FL \u5f15\u5165\u4e86\u4e09\u5c42\u57fa\u4e8e\u63d2\u4ef6\u7684\u7b97\u5b50\u8c03\u5ea6\u7cfb\u7edf\uff0c\u5b9e\u73b0\u82af\u7247\u65e0\u5173\u7684 FP8 \u8bad\u7ec3\u548c\u63a8\u7406\uff1a</p>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">\u540e\u7aef\u4f18\u5148\u7ea7<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h3><p>\u652f\u6301\u7684\u4f9b\u5e94\u5546\u8bf7\u53c2\u89c1<a class=\"reference internal\" href=\"../getting_started/requirements.html#supported-hardwares\"><span class=\"std std-ref\">\u652f\u6301\u7684\u786c\u4ef6</span></a>\u3002</p>", "a[href=\"features.html#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6846\u67b6\u652f\u6301<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2>", "a[href=\"features.html#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u591a\u4f9b\u5e94\u5546\u786c\u4ef6\u652f\u6301<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>TransformerEngine-FL \u901a\u8fc7\u63d2\u4ef6\u7cfb\u7edf\u652f\u6301\u8de8\u591a\u4e2a\u786c\u4ef6\u4f9b\u5e94\u5546\u7684 FP8 \u8bad\u7ec3\u548c\u63a8\u7406\u3002\u65b0\u7684\u4f9b\u5e94\u5546\u540e\u7aef\u53ef\u4ee5\u901a\u8fc7\u63d2\u4ef6\u53d1\u73b0\u673a\u5236\u6dfb\u52a0\uff0c\u65e0\u9700\u4fee\u6539\u6838\u5fc3\u4ee3\u7801\u3002</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u63d2\u4ef6\u7cfb\u7edf<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>TransformerEngine-FL \u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">transformer_engine/plugin/</span></code> \u4e2d\u6dfb\u52a0\u4e86\u57fa\u4e8e\u63d2\u4ef6\u7684\u7b97\u5b50\u8c03\u5ea6\u7cfb\u7edf\u3002\u5b83\u5141\u8bb8\u5728\u8fd0\u884c\u65f6\u6ce8\u518c\u548c\u9009\u62e9\u66ff\u4ee3\u7684\u540e\u7aef\u5b9e\u73b0\uff0c\u65e0\u9700\u4fee\u6539\u6838\u5fc3\u5e93\u5373\u53ef\u5b9e\u73b0\u591a\u82af\u7247\u652f\u6301\u3002</p><p>\u63d2\u4ef6\u7cfb\u7edf\u5305\u62ec\uff1a</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
